#include <cstdio>
#include <cstdlib>
#include <vector>
#include <thread>
#include <atomic>
#include <algorithm>
#include <string>

struct Node { Node* l; Node* r; };

struct Arena {
    std::vector<Node> buf;
    size_t top = 0;
    void reserve(size_t n) { if (buf.size() < n) buf.resize(n); }
    inline Node* alloc() { return &buf[top++]; }
    void reset() { top = 0; }
};

static Node* make(Arena& a, int d) {
    Node* n = a.alloc();
    if (d > 0) {
        n->l = make(a, d - 1);
        n->r = make(a, d - 1);
    } else {
        n->l = nullptr;
        n->r = nullptr;
    }
    return n;
}

static long check(const Node* n) {
    return n->l ? 1 + check(n->l) + check(n->r) : 1;
}

int main(int argc, char** argv) {
    int N = 0;
    if (argc > 1) N = std::atoi(argv[1]);
    const int minDepth = 4;
    const int maxDepth = std::max(minDepth + 2, N);
    const int stretchDepth = maxDepth + 1;

    {
        Arena a;
        a.reserve((size_t)1 << (stretchDepth + 1));
        Node* s = make(a, stretchDepth);
        std::printf("stretch tree of depth %d\t check: %ld\n", stretchDepth, check(s));
    }

    Arena longArena;
    longArena.reserve((size_t)1 << (maxDepth + 1));
    Node* longLived = make(longArena, maxDepth);

    unsigned nthreads = std::thread::hardware_concurrency();
    if (nthreads == 0) nthreads = 4;
    if (nthreads > 64) nthreads = 64;

    std::vector<Arena> arenas(nthreads);
    std::vector<std::string> lines;

    for (int d = minDepth; d <= maxDepth; d += 2) {
        long iterations = 1L << (maxDepth - d + minDepth);
        std::atomic<long> next(0);
        std::vector<long> partial(nthreads, 0);
        const long chunk = 64;
        size_t need = (size_t)1 << (d + 1);
        std::vector<std::thread> threads;
        for (unsigned t = 0; t < nthreads; ++t) {
            threads.emplace_back([&, t]() {
                Arena& a = arenas[t];
                a.reserve(need);
                long sum = 0;
                for (;;) {
                    long start = next.fetch_add(chunk);
                    if (start >= iterations) break;
                    long end = std::min(start + chunk, iterations);
                    for (long i = start; i < end; ++i) {
                        a.reset();
                        Node* r = make(a, d);
                        sum += check(r);
                    }
                }
                partial[t] = sum;
            });
        }
        for (auto& th : threads) th.join();
        long total = 0;
        for (long p : partial) total += p;
        char buf[128];
        std::snprintf(buf, sizeof(buf), "%ld\t trees of depth %d\t check: %ld\n", iterations, d, total);
        lines.push_back(buf);
    }

    for (auto& s : lines) std::fputs(s.c_str(), stdout);
    std::printf("long lived tree of depth %d\t check: %ld\n", maxDepth, check(longLived));
    return 0;
}
