            int d = (int)(idx / Fact[i]);
            count[i] = d;
            idx = idx % Fact[i];
            for (int j = 0; j <= i; ++j) p[j] = pp[j];
            for (int j = 0; j <= i; ++j) {
                pp[j] = (j + d <= i) ? p[j + d] : p[j + d - i - 1];
            }
        }
    }

    inline void nextPermutation() {
        int first = pp[1];
        pp[1] = pp[0];
        pp[0] = first;
        int i = 1;
        while (++count[i] > i) {
            count[i++] = 0;
            int next = pp[0] = pp[1];
            for (int j = 1; j < i; ++j) pp[j] = pp[j + 1];
            pp[i] = first;
            first = next;
        }
    }

    inline int countFlips() {
        int flips = 1;
        int first = pp[0];
        if (pp[first] != 0) {
            for (int i = 0; i < n; ++i) p[i] = pp[i];
            do {
                ++flips;
                for (int lo = 1, hi = first - 1; lo < hi; ++lo, --hi) {
                    int t = p[lo]; p[lo] = p[hi]; p[hi] = t;
                }
                int t = p[first]; p[first] = first; first = t;
            } while (p[first] != 0);
        }
        return flips;
    }

    void runTask(long long task) {
        long long idxMin = task * CHUNKSZ;
        long long idxMax = std::min(Fact[n], idxMin + CHUNKSZ);
        if (idxMin >= idxMax) { maxFlipsArr[task] = 0; chkSumArr[task] = 0; return; }
        firstPermutation(idxMin);
        int maxflips = 0;
        long long chksum = 0;
        for (long long i = idxMin;;) {
            if (pp[0] != 0) {
                int flips = countFlips();
                if (flips > maxflips) maxflips = flips;
                chksum += (i % 2 == 0) ? flips : -flips;
            }
            if (++i == idxMax) break;
            nextPermutation();
        }
        maxFlipsArr[task] = maxflips;
        chkSumArr[task] = chksum;
    }

    void run() {
        for (;;) {
            long long t = taskId.fetch_add(1);
            if (t >= NTASKS) break;
            runTask(t);
        }
    }
};

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    n = atoi(argv[1]);
    if (n < 1) n = 1;
    if (n > 16) n = 16;

    Fact[0] = 1;
    for (int i = 1; i <= n; ++i) Fact[i] = Fact[i - 1] * i;

    unsigned hw = std::thread::hardware_concurrency();
    if (hw == 0) hw = 4;
    long long total = Fact[n];
    long long desiredTasks = (long long)hw * 32;
    if (desiredTasks > total) desiredTasks = total;
    if (desiredTasks < 1) desiredTasks = 1;
    CHUNKSZ = (total + desiredTasks - 1) / desiredTasks;
    if (CHUNKSZ < 1) CHUNKSZ = 1;
    NTASKS = (total + CHUNKSZ - 1) / CHUNKSZ;

    maxFlipsArr.assign(NTASKS, 0);
    chkSumArr.assign(NTASKS, 0);
    taskId.store(0);

    unsigned nthreads = std::min<unsigned>(hw, (unsigned)NTASKS);
    if (nthreads == 0) nthreads = 1;

    std::vector<std::thread> threads;
    std::vector<Worker*> workers(nthreads);
    for (unsigned t = 0; t < nthreads; ++t) {
        workers[t] = new Worker();
        threads.emplace_back([w = workers[t]]() { w->run(); });
    }
    for (auto& th : threads) th.join();
    for (auto* w : workers) delete w;

    long long chk = 0;
    int mx = 0;
    for (long long t = 0; t < NTASKS; ++t) {
        chk += chkSumArr[t];
        if (maxFlipsArr[t] > mx) mx = maxFlipsArr[t];
    }

    printf("%lld\nPfannkuchen(%d) = %d\n", chk, n, mx);
    return 0;
}
