static int bytesPerRow;
static std::vector<double> cr0;
static unsigned char* buf;
static std::atomic<int> nextRow;

static void computeRow(int y) {
    const double ci = 2.0 * y / N - 1.0;
    unsigned char* row = buf + (size_t)y * bytesPerRow;
    for (int bx = 0; bx < bytesPerRow; ++bx) {
        double cr[8], zr[8], zi[8];
        const int base = bx * 8;
        for (int k = 0; k < 8; ++k) {
            int x = base + k;
            cr[k] = (x < N) ? cr0[x] : 0.0;
            zr[k] = 0.0;
            zi[k] = 0.0;
        }
        unsigned bits = 0xFF;
        for (int g = 0; g < 10; ++g) {
            for (int j = 0; j < 5; ++j) {
                for (int k = 0; k < 8; ++k) {
                    double tr = zr[k] * zr[k];
                    double ti = zi[k] * zi[k];
                    zi[k] = 2.0 * zr[k] * zi[k] + ci;
                    zr[k] = tr - ti + cr[k];
                }
            }
            unsigned esc = 0;
            for (int k = 0; k < 8; ++k) {
                double m = zr[k] * zr[k] + zi[k] * zi[k];
                esc |= (m > 4.0) ? (0x80u >> k) : 0u;
            }
            bits &= ~esc;
            if (bits == 0) break;
        }
        row[bx] = (unsigned char)bits;
    }
    int r = N & 7;
    if (r) {
        unsigned mask = (0xFFu << (8 - r)) & 0xFFu;
        row[bytesPerRow - 1] &= (unsigned char)mask;
    }
}

static void worker() {
    for (;;) {
        int y = nextRow.fetch_add(1, std::memory_order_relaxed);
        if (y >= N) break;
        computeRow(y);
    }
}

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    N = atoi(argv[1]);
    if (N <= 0) return 1;
    bytesPerRow = (N + 7) / 8;
    cr0.resize((size_t)bytesPerRow * 8);
    for (int x = 0; x < N; ++x) cr0[x] = 2.0 * x / N - 1.5;
    buf = (unsigned char*)malloc((size_t)bytesPerRow * N);
    if (!buf) return 1;
    nextRow.store(0);

