        2.85885980666130812e-04 * SOLAR_MASS
    },
    { // Uranus
        1.28943695621391310e+01, -1.51111514016986312e+01, -2.23307578892655734e-01,
        2.96460137564761618e-03 * DAYS_PER_YEAR,
        2.37847173959480950e-03 * DAYS_PER_YEAR,
        -2.96589568540237556e-05 * DAYS_PER_YEAR,
        4.36624404335156298e-05 * SOLAR_MASS
    },
    { // Neptune
        1.53796971148509165e+01, -2.59193146099879641e+01, 1.79258772950371181e-01,
        2.68067772490389322e-03 * DAYS_PER_YEAR,
        1.62824170038242295e-03 * DAYS_PER_YEAR,
        -9.51592254519715870e-05 * DAYS_PER_YEAR,
        5.15138902046611451e-05 * SOLAR_MASS
    }
};

static void offset_momentum() {
    double px = 0, py = 0, pz = 0;
    for (int i = 0; i < NBODIES; ++i) {
        px += bodies[i].vx * bodies[i].mass;
        py += bodies[i].vy * bodies[i].mass;
        pz += bodies[i].vz * bodies[i].mass;
    }
    bodies[0].vx = -px / SOLAR_MASS;
    bodies[0].vy = -py / SOLAR_MASS;
    bodies[0].vz = -pz / SOLAR_MASS;
}

static double energy() {
    double e = 0.0;
    for (int i = 0; i < NBODIES; ++i) {
        const Body& b = bodies[i];
        e += 0.5 * b.mass * (b.vx * b.vx + b.vy * b.vy + b.vz * b.vz);
        for (int j = i + 1; j < NBODIES; ++j) {
            const Body& c = bodies[j];
            double dx = b.x - c.x, dy = b.y - c.y, dz = b.z - c.z;
            e -= (b.mass * c.mass) / std::sqrt(dx * dx + dy * dy + dz * dz);
        }
    }
    return e;
}

static void advance(long n, double dt) {
    // Precompute pair indices.
    int pi_[NPAIRS], pj_[NPAIRS];
    {
        int k = 0;
        for (int i = 0; i < NBODIES; ++i)
            for (int j = i + 1; j < NBODIES; ++j) { pi_[k] = i; pj_[k] = j; ++k; }
    }

    alignas(32) double rx[NPAIRS], ry[NPAIRS], rz[NPAIRS], mag[NPAIRS];

    for (long step = 0; step < n; ++step) {
        for (int k = 0; k < NPAIRS; ++k) {
            const Body& a = bodies[pi_[k]];
            const Body& b = bodies[pj_[k]];
            rx[k] = a.x - b.x;
            ry[k] = a.y - b.y;
            rz[k] = a.z - b.z;
        }
        for (int k = 0; k < NPAIRS; ++k) {
            double d2 = rx[k] * rx[k] + ry[k] * ry[k] + rz[k] * rz[k];
            double dist = std::sqrt(d2);
            mag[k] = dt / (d2 * dist);
        }
        for (int k = 0; k < NPAIRS; ++k) {
            Body& a = bodies[pi_[k]];
            Body& b = bodies[pj_[k]];
            double ma = a.mass * mag[k];
            double mb = b.mass * mag[k];
            a.vx -= rx[k] * mb;
            a.vy -= ry[k] * mb;
            a.vz -= rz[k] * mb;
            b.vx += rx[k] * ma;
            b.vy += ry[k] * ma;
            b.vz += rz[k] * ma;
        }
        for (int i = 0; i < NBODIES; ++i) {
            Body& b = bodies[i];
            b.x += dt * b.vx;
            b.y += dt * b.vy;
            b.z += dt * b.vz;
        }
    }
