static inline double eval_A(int i, int j) {
    int ij = i + j;
    return 1.0 / (double)(ij * (ij + 1) / 2 + i + 1);
}

static void mul_Av_range(int n, const double* v, double* Av, int lo, int hi) {
    for (int i = lo; i < hi; ++i) {
        double sum = 0.0;
        for (int j = 0; j < n; ++j) sum += eval_A(i, j) * v[j];
        Av[i] = sum;
    }
}

static void mul_Atv_range(int n, const double* v, double* Atv, int lo, int hi) {
    for (int i = lo; i < hi; ++i) {
        double sum = 0.0;
        for (int j = 0; j < n; ++j) sum += eval_A(j, i) * v[j];
        Atv[i] = sum;
    }
}

static int nthreads = 1;

template <typename F>
static void parallel_rows(int n, F f) {
    if (nthreads <= 1 || n < 64) { f(0, n); return; }
    std::vector<std::thread> th;
    th.reserve(nthreads);
    int chunk = (n + nthreads - 1) / nthreads;
    for (int t = 0; t < nthreads; ++t) {
        int lo = t * chunk;
        int hi = std::min(n, lo + chunk);
        if (lo >= hi) break;
        th.emplace_back([=]() { f(lo, hi); });
    }
    for (auto& x : th) x.join();
}

static void mul_AtAv(int n, const double* v, double* tmp, double* AtAv) {
    parallel_rows(n, [&](int lo, int hi) { mul_Av_range(n, v, tmp, lo, hi); });
    parallel_rows(n, [&](int lo, int hi) { mul_Atv_range(n, tmp, AtAv, lo, hi); });
}

int main(int argc, char** argv) {
